use std::fmt::Write;

use schemars::{JsonSchema, generate::SchemaSettings};
use strum::IntoEnumIterator;

use super::config::{
    DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig, LoaderConfig,
};
use crate::domain::models::entity_ingestion::{DeclarationIngestionStage, MemberIngestionStage};

fn introduction() -> String {
    "Path to a YAML configuration file.\nRelative data_dir paths resolve against the current working directory.\n".to_owned()
}

fn fields<T: JsonSchema>(help: &mut String, label: &str, database: bool) {
    let schema = SchemaSettings::draft2020_12()
        .for_deserialize()
        .into_generator()
        .into_root_schema_for::<T>();
    write!(help, "\n{label}:\n").expect("writing to a String succeeds");
    let schema = schema.as_value();
    let required = schema["required"].as_array();
    for (name, field) in schema["properties"]
        .as_object()
        .expect("configuration schema has fields")
    {
        let presence = if required.is_some_and(|names| names.iter().any(|value| value == name)) {
            "required"
        } else {
            "optional"
        };
        write!(
            help,
            "  {name} ({}, {presence}",
            field["type"]
                .as_str()
                .expect("configuration field has a primitive type")
        )
        .expect("writing to a String succeeds");
        if let Some(default) = field.get("default") {
            write!(help, ", default {default}").expect("writing to a String succeeds");
        }
        writeln!(
            help,
            "):\n    {}",
            field["description"].as_str().unwrap_or_default()
        )
        .expect("writing to a String succeeds");
    }
    if database {
        help.push_str("  Environment: DATABASE_URL is required separately from the YAML file.\n");
    }
}

pub(super) fn store() -> String {
    let mut help = introduction();
    fields::<LoaderConfig>(&mut help, "Fields", false);
    help
}

pub(super) fn declarations() -> String {
    let mut help = introduction();
    for stage in DeclarationIngestionStage::iter() {
        match stage {
            DeclarationIngestionStage::Fetch => {
                fields::<DeclarationFetcherConfig>(&mut help, "fetch", true);
            }
            DeclarationIngestionStage::Clean => fields::<LoaderConfig>(&mut help, "clean", false),
            DeclarationIngestionStage::Resolve => {
                fields::<DeclarationResolverConfig>(&mut help, "resolve", false);
            }
            DeclarationIngestionStage::Load => fields::<LoaderConfig>(&mut help, "load", true),
        }
    }
    help
}

pub(super) fn members() -> String {
    let mut help = introduction();
    for stage in MemberIngestionStage::iter() {
        match stage {
            MemberIngestionStage::Fetch => fields::<FetcherConfig>(&mut help, "fetch", false),
            MemberIngestionStage::Load => fields::<LoaderConfig>(&mut help, "load", true),
        }
    }
    help
}
use std::future::Future;

use schemars::{JsonSchema, Schema, generate::SchemaSettings};
use serde::Serialize;
use strum::IntoEnumIterator;

use super::{CliSuccess, response::ErrorResponse};
use crate::domain::models::entity_ingestion::DeclarationIngestionStage;

fn schema<T: JsonSchema>() -> Schema {
    SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator()
        .into_root_schema_for::<T>()
}

trait ResponseSchema {
    fn schema() -> Schema;
}

impl<T: Serialize + JsonSchema, E> ResponseSchema for Result<CliSuccess<T>, E> {
    fn schema() -> Schema {
        schema::<T>()
    }
}

pub(super) trait HandlerSchema<Args> {
    fn response_schema(self) -> Schema;
}

macro_rules! handler_schema {
    ($($arg:ident),*) => {
        impl<F, Fut, $($arg,)*> HandlerSchema<($($arg,)*)> for F
        where
            F: FnOnce($($arg),*) -> Fut,
            Fut: Future,
            Fut::Output: ResponseSchema,
        {
            fn response_schema(self) -> Schema {
                <Fut::Output as ResponseSchema>::schema()
            }
        }
    };
}

handler_schema!();
handler_schema!(A);
handler_schema!(A, B);
handler_schema!(A, B, C);

fn section(label: &str, schema: &Schema) -> String {
    format!(
        "{label}\n{}\n",
        serde_json::to_string_pretty(schema).expect("JSON schema serializes")
    )
}

fn failure() -> String {
    format!(
        "Success: one JSON document on stdout, exit 0.\nCommand failure: one JSON document on stderr, exit 1.\nClap argument errors and help use Clap's text output.\nSchemas use JSON Schema draft 2020-12.\n\n{}",
        section("Failure JSON schema:", &schema::<ErrorResponse>())
    )
}

pub(super) fn single<Args>(handler: impl HandlerSchema<Args>) -> String {
    format!(
        "{}\n{}",
        section("Success JSON schema:", &handler.response_schema()),
        failure()
    )
}

pub(super) fn declarations() -> String {
    let mut help = String::new();
    for stage in DeclarationIngestionStage::iter() {
        let mut schema = match stage {
            DeclarationIngestionStage::Fetch => super::fetch_declarations.response_schema(),
            DeclarationIngestionStage::Clean => super::clean_declarations.response_schema(),
            DeclarationIngestionStage::Resolve => super::resolve_declarations.response_schema(),
            DeclarationIngestionStage::Load => super::load_declarations.response_schema(),
        };
        if stage == DeclarationIngestionStage::Fetch {
            schema
                .as_object_mut()
                .expect("response schema is an object")["properties"]["stage"]["const"] =
                serde_json::to_value(&stage).expect("stage serializes");
        }
        let label = serde_json::to_value(&stage).expect("stage serializes");
        help.push_str(&section(
            &format!(
                "Success JSON schema ({}):",
                label.as_str().expect("stage is a string")
            ),
            &schema,
        ));
        help.push('\n');
    }
    help.push_str(&failure());
    help
}
