use clap::Parser;
use exposed::inbound::cli::DataArgs;
use tempfile::TempDir;

const COMMANDS: &[&[&str]] = &[
    &["latest"],
    &["copy-latest-raw"],
    &["declarations", "fetch"],
    &["declarations", "clean"],
    &["declarations", "resolve"],
    &["declarations", "load"],
    &["members", "fetch"],
